changeSet.sql:
ALTER TABLE str_rn.registration_number
    DROP CONSTRAINT IF EXISTS chk_rn_status;
ALTER TABLE str_rn.registration_number
    ADD CONSTRAINT chk_rn_status
        CHECK (status IN ('ACTIVE', 'SUSPENSION_PROPOSED', 'SUSPENDED', 'WITHDRAWAL_PROPOSED',
                          'REVOKED', 'WITHDRAWN'));
ALTER TABLE str_rn.registration_number
    ADD COLUMN withdrawal_deadline DATE;
ALTER TABLE str_rn.registration_number
    ADD COLUMN withdrawal_from_suspended BOOLEAN NOT NULL DEFAULT false;

